cypress_script:
describe('Alert and Confirm Dialogs', () => {
  it('should display an alert dialog when the alert button is clicked', () => {
    cy.visit('https://demoqa.com/alerts');
    cy.get('#alertButton').click();
    cy.on('window:alert', (txt) => {
      expect(txt).to.exist;
    });
  });

  it('should display a confirmation dialog when the confirm button is clicked', () => {
    cy.visit('https://demoqa.com/alerts');
    cy.get('#confirmButton').click();
    cy.on('window:confirm', (txt) => {
      expect(txt).to.exist;
    });
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Alert and Confirm Dialogs', () => {
  test('should display an alert dialog when the alert button is clicked', async ({ page }) => {
    await page.goto('https://demoqa.com/alerts');
    page.on('dialog', dialog => {
      expect(dialog.type()).toBe('alert');
      dialog.accept();
    });
    await page.click('#alertButton');
  });

  test('should display a confirmation dialog when the confirm button is clicked', async ({ page }) => {
    await page.goto('https://demoqa.com/alerts');
    page.on('dialog', dialog => {
      expect(dialog.type()).toBe('confirm');
      dialog.accept();
    });
    await page.click('#confirmButton');
  });
});
